import {inflateSync} from 'node:zlib';
// Public Robinhood chain 4663 runtime bytes captured read-only September 13 2026.
// Tests verify hashes against the deployed manifest; no network is used.
const COMPRESSED_RUNTIME = {"implementation":"","registry":""};
export const CODE=Object.fromEntries(Object.entries(COMPRESSED_RUNTIME).map(([role,data])=>[role,`0x${inflateSync(Buffer.from(data,'base64')).toString('hex')}`]));
